<div class="border-t border-[#262626] bg-black px-4 py-4 sm:px-6"><div x-show="replyingTo" x-cloak class="mb-2 flex items-center justify-between rounded-lg bg-[#1c1c1c] px-3 py-2 text-xs text-[#a8a8a8]"><span>Replying to <strong class="text-white" x-text="replyingTo?.user?.username"></strong>: <span x-text="replyingTo?.message"></span></span><button type="button" @click="replyingTo=null">×</button></div><form @submit.prevent="sendMessage" class="flex items-end gap-2 rounded-3xl border border-[#363636] bg-[#121212] px-3 py-2"><button type="button" @click="pickerOpen=!pickerOpen" class="text-xl" aria-label="Emoji picker">☺</button><textarea x-ref="messageInput" x-model="newMessage" @input="$el.style.height='auto';$el.style.height=Math.min($el.scrollHeight,120)+'px'" rows="1" maxlength="5000" placeholder="Message..." class="max-h-[120px] min-h-[24px] flex-1 resize-none border-0 bg-transparent py-1 text-sm text-white outline-none placeholder-[#737373] focus:ring-0"></textarea><input type="file" class="hidden" x-ref="attachment" accept="image/*,video/*"><button type="button" @click="$refs.attachment.click()" class="text-xl" aria-label="Add image or attachment">＋</button><button type="button" class="text-lg" aria-label="Voice note">🎙</button><button type="button" @click="pickerOpen=true" class="text-xs font-bold text-[#a8a8a8]" aria-label="Sticker and GIF picker">GIF</button><button type="submit" :disabled="!newMessage.trim()||sending" class="px-1 text-sm font-semibold text-[#0095f6] transition-opacity disabled:opacity-0">Send</button></form></div>
